import csv
import io
import json


def to_csv(rows: list) -> str:
    """Export rows to CSV format."""
    if not rows:
        return ""
    out = io.StringIO()
    writer = csv.DictWriter(out, fieldnames=list(rows[0]))
    writer.writeheader()
    writer.writerows(rows)
    return out.getvalue()


def to_tsv(rows: list) -> str:
    """Export rows to TSV (tab-separated values) format."""
    if not rows:
        return ""
    out = io.StringIO()
    writer = csv.DictWriter(out, fieldnames=list(rows[0]), delimiter='\t')
    writer.writeheader()
    writer.writerows(rows)
    return out.getvalue()


def to_json(rows: list) -> str:
    """Export rows to JSON format."""
    return json.dumps(rows, indent=2)


def export(rows: list, format: str = "csv") -> str:
    """
    Export rows to the specified format.

    Args:
        rows: List of dictionaries to export
        format: Export format - "csv", "tsv", or "json"

    Returns:
        String representation of the exported data
    """
    if format.lower() == "csv":
        return to_csv(rows)
    elif format.lower() == "tsv":
        return to_tsv(rows)
    elif format.lower() == "json":
        return to_json(rows)
    else:
        raise ValueError(f"Unsupported format: {format}. Supported formats: 'csv', 'tsv', 'json'")"}}
