from export.exporter import to_csv, to_tsv, to_json, export


class ExporterTest(unittest.TestCase):
    def test_csv(self):
        self.assertEqual(to_csv([{"a": 1}]), "a\r\n1\r\n")

    def test_csv_multiple(self):
        data = [{"a": 1, "b": 2}, {"a": 3, "b": 4}]
        expected = "a,b\r\n1,2\r\n3,4\r\n"
        self.assertEqual(to_csv(data), expected)

    def test_tsv(self):
        self.assertEqual(to_tsv([{"a": 1}]), "a\r\n1\r\n".replace(",", "\t"))

    def test_tsv_multiple(self):
        data = [{"a": 1, "b": 2}, {"a": 3, "b": 4}]
        expected = "a\tb\r\n1\t2\r\n3\t4\r\n"
        self.assertEqual(to_tsv(data), expected)

    def test_json(self):
        self.assertEqual(to_json([{"a": 1}]), '[\n  {\n    "a": 1\n  }\n]')

    def test_json_multiple(self):
        data = [{"a": 1, "b": 2}, {"a": 3, "b": 4}]
        expected = '[\n  {\n    "a": 1,\n    "b": 2\n  },\n  {\n    "a": 3,\n    "b": 4\n  }\n]'
        self.assertEqual(to_json(data), expected)

    def test_empty_csv(self):
        self.assertEqual(to_csv([]), "")

    def test_empty_tsv(self):
        self.assertEqual(to_tsv([]), "")

    def test_empty_json(self):
        self.assertEqual(to_json([]), "[]")

    def test_export_csv(self):
        self.assertEqual(export([{"a": 1}], "csv"), "a\r\n1\r\n")

    def test_export_tsv(self):
        self.assertEqual(export([{"a": 1}], "tsv"), "a\r\n1\r\n".replace(",", "\t"))

    def test_export_json(self):
        self.assertEqual(export([{"a": 1}], "json"), '[\n  {\n    "a": 1\n  }\n]')

    def test_export_default(self):
        self.assertEqual(export([{"a": 1}]), "a\r\n1\r\n")

    def test_export_invalid_format(self):
        with self.assertRaises(ValueError) as context:
            export([{"a": 1}], "invalid")
        self.assertIn("Unsupported format", str(context.exception))


if __name__ == '__main__':
    unittest.main()"}}
